MODULE_BY_KEY = {module.key: module for module in MODULES}
WORKSPACES = tuple(dict.fromkeys(module.workspace for module in MODULES))


def module_rows() -> list[dict[str, object]]:
    return [asdict(module) for module in MODULES]


def workspace_modules(workspace: str) -> tuple[NeuroModuleSpec, ...]:
    return tuple(module for module in MODULES if module.workspace == workspace)
